// analyzer/dataClasses.ts:91
pub(crate) fn get_inherited_data_class_slots_names(class_type: ClassType) -> JsSet<String> {
    let mut inherited_slots_names: JsSet<String> = JsSet::default();
    let mro_tail: Vec<P<Type>> = class_type
        .d()
        .shared
        .get()
        .mro
        .borrow()
        .iter()
        .skip(1)
        .copied()
        .collect();
    for mro_class in mro_tail {
        if is_instantiable_class(mro_class) {
            let mro_class = ClassType(mro_class);
            let synthesize_deferred = mro_class
                .d()
                .shared
                .get()
                .synthesize_data_class_slots_deferred
                .borrow()
                .clone();
            if let Some(synthesize_deferred) = synthesize_deferred {
                synthesize_deferred.call();
            }
            let local_slots_names = mro_class
                .d()
                .shared
                .get()
                .local_slots_names
                .borrow()
                .clone();
            if let Some(local_slots_names) = local_slots_names {
                for name in local_slots_names {
                    inherited_slots_names.insert(name);
                }
            }
        }
    }
    inherited_slots_names
}

// analyzer/dataClasses.ts:102
pub(crate) fn is_data_class_keyword_only_separator(
    evaluator: &TypeEvaluator,
    symbol: Option<P<Symbol>>,
    annotation_node: ExpressionNode,
) -> bool {
    if symbol.is_some_and(|symbol| symbol.is_data_class_keyword_only()) {
        return true;
    }

    let annotated_type = evaluator.get_type_of_annotation(
        annotation_node,
        Some(&ExpectedTypeOptions {
            allow_final: Some(true),
            allow_class_var: Some(true),
            var_type_annotation: Some(true),
            ..Default::default()
        }),
    );
    is_class_instance(annotated_type)
        && ClassType::is_built_in(ClassType(annotated_type), Some(&[jsrt::atom!("KW_ONLY")]))
}

// analyzer/dataClasses.ts:120
// Calculate generated slots without forcing deferred dataclass method synthesis.
pub fn synthesize_data_class_slots(evaluator: &TypeEvaluator, class_type: ClassType) {
    let shared = class_type.d().shared.get();
    *shared.synthesize_data_class_slots_deferred.borrow_mut() = None;

    if !ClassType::is_data_class_generate_slots(class_type)
        || shared.local_slots_names.borrow().is_some()
    {
        return;
    }

    let inherited_slots_names = get_inherited_data_class_slots_names(class_type);
    let mut local_slots_names: Vec<String> = vec![];
    let local_fields = shared.fields.get().entries();

    let synthesize_methods_deferred = shared.synthesize_methods_deferred.borrow_mut().take();
    for (name, symbol) in local_fields {
        if symbol.is_ignored_for_protocol_match() || name == "__hash__" {
            continue;
        }

        let mut variable_decl = symbol.get_typed_declarations().into_iter().find(|decl| {
            if decl.type_ != DeclarationType::Variable {
                return false;
            }

            let container = get_enclosing_class_or_function(decl.node.get());
            container.map(|container| container.node_type) == Some(ParseNodeType::Class)
        });

        if variable_decl.is_none() {
            variable_decl = symbol.get_declarations().iter().copied().find(|decl| {
                decl.type_ == DeclarationType::Variable
                    && decl
                        .d().variable()
                        .unwrap()
                        .type_annotation_node
                        .get()
                        .is_none()
                    && decl.d().variable().unwrap().is_final.get().unwrap_or(false)
            });
        }

        if variable_decl
            .and_then(|decl| decl.node.get().parent.get())
            .map(|parent| parent.node_type)
            != Some(ParseNodeType::TypeAnnotation)
        {
            variable_decl = None;
        }

        let is_keyword_only_separator = match variable_decl
            .and_then(|decl| decl.d().variable().unwrap().type_annotation_node.get())
        {
            Some(type_annotation_node) => {
                is_data_class_keyword_only_separator(evaluator, Some(symbol), type_annotation_node)
            }
            None => false,
        };

        if variable_decl.is_some()
            && !symbol.is_class_var()
            && !symbol.is_init_var()
            && !is_keyword_only_separator
            && !inherited_slots_names.contains(name.as_str())
        {
            local_slots_names.push(name.to_string());
        }
    }
    // The TypeScript `finally` block.
    if let Some(synthesize_methods_deferred) = synthesize_methods_deferred {
        let has_deferred = shared.synthesize_methods_deferred.borrow().is_some();
        if !has_deferred {
            *shared.synthesize_methods_deferred.borrow_mut() = Some(synthesize_methods_deferred);
        }
    }

    let has_non_empty_slots = !local_slots_names.is_empty();
    *shared.local_slots_names.borrow_mut() = Some(local_slots_names);
    shared.has_non_empty_slots.set(Some(has_non_empty_slots));
}

// analyzer/dataClasses.ts:188
// Validates fields for compatibility with a dataclass and synthesizes
// an appropriate __new__ and __init__ methods plus __dataclass_fields__
// and __match_args__ class variables.
#[allow(clippy::too_many_arguments)]
pub fn synthesize_data_class_methods(
    evaluator: &TypeEvaluator,
    node: ClassNode,
    class_type: ClassType,
    is_named_tuple: bool,
    skip_synthesize_init: bool,
    has_existing_init_method: bool,
    skip_synthesize_hash: bool,
    node_info: &AnalyzerNodeInfoAccessor,
) {
    assert!(ClassType::is_data_class(class_type) || is_named_tuple);

    let class_type_var = synthesize_type_var_for_self_cls(class_type, /* isClsParam */ true);
    let new_type =
        FunctionType::create_synthesized_instance("__new__", FunctionTypeFlags::ConstructorMethod);
    let new_constructor_scope_id = get_type_var_scope_id(class_type.0);
    new_type
        .d()
        .priv_
        .borrow_mut()
        .constructor_type_var_scope_id = new_constructor_scope_id;
    let init_type = FunctionType::create_synthesized_instance("__init__", FunctionTypeFlags::None);
    let init_constructor_scope_id = get_type_var_scope_id(class_type.0);
    init_type
        .d()
        .priv_
        .borrow_mut()
        .constructor_type_var_scope_id = init_constructor_scope_id;

    // Generate both a __new__ and an __init__ method. The parameters of the
    // __new__ method are based on field definitions for NamedTuple classes,
    // and the parameters of the __init__ method are based on field definitions
    // in other cases.
    FunctionType::add_param(
        new_type,
        &FunctionParam::create(
            ParamCategory::Simple,
            class_type_var.0,
            FunctionParamFlags::TypeDeclared,
            Some("cls"),
            None,
            None,
        ),
    );
    if !is_named_tuple {
        FunctionType::add_default_params(new_type, false);
        let new_shared = new_type.d().shared.get();
        new_shared
            .flags
            .set(new_shared.flags.get() | FunctionTypeFlags::GradualCallableForm);
    }
    new_type
        .d()
        .shared
        .get()
        .declared_return_type
        .set(Some(convert_to_instance(class_type_var.0, true)));

    let self_type = synthesize_type_var_for_self_cls(class_type, /* isClsParam */ false);
    let self_param = FunctionParam::create(
        ParamCategory::Simple,
        self_type.0,
        FunctionParamFlags::TypeDeclared,
        Some("self"),
        None,
        None,
    );
    FunctionType::add_param(init_type, &self_param);
    if is_named_tuple {
        FunctionType::add_default_params(init_type, false);
        let init_shared = init_type.d().shared.get();
        init_shared
            .flags
            .set(init_shared.flags.get() | FunctionTypeFlags::GradualCallableForm);
    }
    init_type
        .d()
        .shared
        .get()
        .declared_return_type
        .set(Some(evaluator.get_none_type()));

    // For Python 3.13 and newer, synthesize a __replace__ method.
    let mut replace_type: Option<FunctionType> = None;
    if PythonVersion::is_greater_or_equal_to(
        &node_info
            .get_file_info(node.0)
            .execution_environment
            .python_version,
        &PYTHON_VERSION3_13,
    ) {
        let new_replace_type =
            FunctionType::create_synthesized_instance("__replace__", FunctionTypeFlags::None);
        FunctionType::add_param(new_replace_type, &self_param);
        FunctionType::add_keyword_only_param_separator(new_replace_type);
        new_replace_type
            .d()
            .shared
            .get()
            .declared_return_type
            .set(Some(self_type.0));
        replace_type = Some(new_replace_type);
    }

    // Maintain a list of all dataclass entries (including
    // those from inherited classes) plus a list of only those
    // entries added by this class.
    let mut local_data_class_entries: Vec<P<DataClassEntry>> = vec![];
    let mut full_data_class_entries: Vec<P<DataClassEntry>> = vec![];
    let mut named_tuple_entries: JsSet<String> = JsSet::default();
    let all_ancestors_known =
        add_inherited_data_class_entries(class_type, &mut full_data_class_entries);

    if !all_ancestors_known {
        // If one or more ancestor classes have an unknown type, we cannot
        // safely determine the parameter list, so we'll accept any parameters
        // to avoid a false positive.
        FunctionType::add_default_params(init_type, false);

        if let Some(replace_type) = replace_type {
            FunctionType::add_default_params(replace_type, false);
        }
    }

    // Add field-based parameters to either the __new__ or __init__ method
    // based on whether this is a NamedTuple or a dataclass.
    let constructor_type = if is_named_tuple { new_type } else { init_type };

    // Maintain a list of "type evaluators".
    // TS `type EntryTypeEvaluator = () => Type`. Each variant is one of the two closures and
    // holds the statement it captures. The first closure also reads `isInferredFinal` and
    // `defaultExpr` when it runs; nothing writes them after the entry is pushed, so the push
    // records their values.
    #[derive(Clone, Copy)]
    enum EntryTypeEvaluator {
        // analyzer/dataClasses.ts:316
        Assignment(AssignmentNode),
        // analyzer/dataClasses.ts:418
        Annotation(TypeAnnotationNode),
    }
    struct LocalEntryTypeEvaluator {
        entry: P<DataClassEntry>,
        evaluator: EntryTypeEvaluator,
        is_inferred_final: bool,
        default_expr: Option<ExpressionNode>,
    }
    let mut local_entry_type_evaluator: Vec<LocalEntryTypeEvaluator> = vec![];
    let mut saw_keyword_only_separator = false;

    ClassType::get_symbol_table(class_type).for_each(|symbol, name| {
        if symbol.is_ignored_for_protocol_match() {
            return;
        }

        // Apparently, `__hash__` is special-cased in a dataclass. I can't find
        // this in the spec, but the runtime seems to treat is specially.
        if name == "__hash__" {
            return;
        }

        let mut is_inferred_final = false;

        // Only variables (not functions, classes, etc.) are considered.
        let mut class_var_decl = symbol.get_typed_declarations().into_iter().find(|decl| {
            if decl.type_ != DeclarationType::Variable {
                return false;
            }

            let container = get_enclosing_class_or_function(decl.node.get());
            let Some(container) = container else {
                return false;
            };
            if container.node_type != ParseNodeType::Class {
                return false;
            }

            true
        });

        // See if this is an unannotated (inferred) Final value.
        if class_var_decl.is_none() {
            class_var_decl = symbol.get_declarations().iter().copied().find(|decl| {
                decl.type_ == DeclarationType::Variable
                    && decl
                        .d().variable()
                        .unwrap()
                        .type_annotation_node
                        .get()
                        .is_none()
                    && decl.d().variable().unwrap().is_final.get().unwrap_or(false)
            });

            is_inferred_final = true;
        }

        if let Some(class_var_decl) = class_var_decl {
            let mut statement: Option<P<ParseNode>> = Some(class_var_decl.node.get());

            while let Some(cur_statement) = statement {
                if cur_statement.node_type == ParseNodeType::Assignment {
                    break;
                }

                if cur_statement.node_type == ParseNodeType::TypeAnnotation {
                    if cur_statement
                        .parent
                        .get()
                        .is_some_and(|parent| parent.node_type == ParseNodeType::Assignment)
                    {
                        statement = cur_statement.parent.get();
                    }
                    break;
                }

                statement = cur_statement.parent.get();
            }

            let Some(statement) = statement else {
                return;
            };

            let mut variable_name_node: Option<NameNode> = None;
            let mut type_annotation_node: Option<TypeAnnotationNode> = None;
            let mut alias_name: Option<String> = None;
            let mut variable_type_evaluator: Option<EntryTypeEvaluator> = None;
            let mut has_default = false;
            let mut is_default_factory = false;
            let mut is_field_specifier_without_default = false;
            let mut is_keyword_only =
                ClassType::is_data_class_keyword_only(class_type) || saw_keyword_only_separator;
            let mut default_expr: Option<ExpressionNode> = None;
            let mut include_in_init = true;
            let mut converter: Option<ArgumentNode> = None;

            if let Some(assignment_statement) = AssignmentNode::cast(statement) {
                if let Some(left_expr) =
                    TypeAnnotationNode::cast(assignment_statement.d().left_expr.get())
                    && let Some(value_name) = NameNode::cast(left_expr.d().value_expr.get())
                {
                    variable_name_node = Some(value_name);
                    type_annotation_node = Some(left_expr);
                    variable_type_evaluator =
                        Some(EntryTypeEvaluator::Assignment(assignment_statement));
                }

                has_default = true;
                default_expr = Some(assignment_statement.d().right_expr.get());

                // If the RHS of the assignment is assigning a field instance where the
                // "init" parameter is set to false, do not include it in the init method.
                if !is_named_tuple
                    && let Some(right_expr) =
                        CallNode::cast(assignment_statement.d().right_expr.get())
                {
                    let call_type_result = evaluator.get_type_of_expression(
                        right_expr.d().left_expr.get(),
                        EvalFlags::CallBaseDefaults,
                        None,
                    );
                    let call_type = call_type_result.type_.get();

                    let field_descriptor_names = class_type
                        .d()
                        .shared
                        .get()
                        .data_class_behaviors
                        .get()
                        .map(|behaviors| behaviors.field_descriptor_names.borrow().clone())
                        .unwrap_or_default();
                    if !is_named_tuple
                        && is_dataclass_field_constructor(call_type, &field_descriptor_names)
                    {
                        let args: Vec<ArgumentNode> = right_expr.d().args.borrow().clone();
                        let find_arg = |arg_name: &str| {
                            args.iter().copied().find(|arg| {
                                arg.d()
                                    .name
                                    .get()
                                    .is_some_and(|name| name.d().value() == arg_name)
                            })
                        };

                        let init_arg = find_arg("init");
                        if let Some(init_arg) = init_arg {
                            let file_info = node_info.get_file_info(node.0);
                            include_in_init = evaluate_static_bool_expression(
                                init_arg.d().value_expr.get(),
                                &file_info.execution_environment,
                                &file_info.defined_constants,
                                None,
                                None,
                            )
                            .unwrap_or(include_in_init);
                        } else {
                            include_in_init = get_default_arg_value_for_field_specifier(
                                evaluator,
                                right_expr,
                                call_type_result,
                                "init",
                            )
                            .unwrap_or(include_in_init);
                        }

                        let kw_only_arg = find_arg("kw_only");
                        if let Some(kw_only_arg) = kw_only_arg {
                            let file_info = node_info.get_file_info(node.0);
                            is_keyword_only = evaluate_static_bool_expression(
                                kw_only_arg.d().value_expr.get(),
                                &file_info.execution_environment,
                                &file_info.defined_constants,
                                None,
                                None,
                            )
                            .unwrap_or(is_keyword_only);
                        } else {
                            is_keyword_only = get_default_arg_value_for_field_specifier(
                                evaluator,
                                right_expr,
                                call_type_result,
                                "kw_only",
                            )
                            .unwrap_or(is_keyword_only);
                        }

                        let default_value_arg = find_arg("default");
                        has_default = default_value_arg.is_some();
                        if let Some(default_value_arg) = default_value_arg {
                            default_expr = Some(default_value_arg.d().value_expr.get());
                        }

                        let default_factory_arg = args.iter().copied().find(|arg| {
                            arg.d().name.get().is_some_and(|name| {
                                name.d().value() == "default_factory" || name.d().value() == "factory"
                            })
                        });
                        if default_factory_arg.is_some() {
                            has_default = true;
                            is_default_factory = true;
                        }
                        if let Some(default_factory_arg) = default_factory_arg {
                            default_expr = Some(default_factory_arg.d().value_expr.get());
                        }

                        is_field_specifier_without_default = !has_default;

                        let alias_arg = find_arg("alias");
                        if let Some(alias_arg) = alias_arg {
                            let value_type = evaluator
                                .get_type_of_expression(
                                    alias_arg.d().value_expr.get(),
                                    EvalFlags::None,
                                    None,
                                )
                                .type_
                                .get();
                            if is_class_instance(value_type)
                                && ClassType::is_built_in(
                                    ClassType(value_type),
                                    Some(&[jsrt::atom!("str")]),
                                )
                                && is_literal_type(ClassType(value_type))
                            {
                                let literal_value = ClassType(value_type)
                                    .d()
                                    .priv_
                                    .borrow()
                                    .literal_value
                                    .clone();
                                alias_name = match literal_value {
                                    Some(LiteralValue::String(value)) => Some(value.to_string_lossy()),
                                    _ => unreachable!("a str literal holds a string"),
                                };
                            }
                        }

                        let converter_arg = find_arg("converter");
                        if let Some(converter_arg) = converter_arg {
                            converter = Some(converter_arg);
                        }
                    }
                }
            } else if let Some(annotation_statement) = TypeAnnotationNode::cast(statement) {
                if let Some(value_name) = NameNode::cast(annotation_statement.d().value_expr.get())
                {
                    variable_name_node = Some(value_name);
                    type_annotation_node = Some(annotation_statement);
                    variable_type_evaluator =
                        Some(EntryTypeEvaluator::Annotation(annotation_statement));
                }
            }

            // Is this a KW_ONLY separator introduced in Python 3.10?
            // Per the Python docs, the variable name and any assigned value are ignored.
            if let Some(name_node) = variable_name_node
                && let Some(annotation_node) = type_annotation_node
                && !is_named_tuple
                && is_data_class_keyword_only_separator(
                    evaluator,
                    class_type
                        .d()
                        .shared
                        .get()
                        .fields
                        .get()
                        .get(name_node.d().value()),
                    annotation_node.d().annotation.get(),
                )
            {
                // CPython raises a TypeError if more than one KW_ONLY
                // separator appears within a single dataclass.
                if saw_keyword_only_separator {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::data_class_duplicate_kw_only()
                            .format(&[("name", name_node.d().value())]),
                        name_node.0,
                        None,
                    );
                }

                saw_keyword_only_separator = true;
                variable_name_node = None;
                type_annotation_node = None;
                variable_type_evaluator = None;
            }

            if let Some(variable_name_node) = variable_name_node
                && let Some(variable_type_evaluator) = variable_type_evaluator
            {
                let variable_name = variable_name_node.d().value().to_string();

                // Named tuples don't allow attributes that begin with an underscore.
                if is_named_tuple && variable_name.starts_with('_') {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::named_tuple_field_underscore(),
                        variable_name_node.0,
                        None,
                    );
                    return;
                }

                // Don't include class vars. PEP 557 indicates that they shouldn't
                // be considered data class entries.
                let variable_symbol = ClassType::get_symbol_table(class_type).get(&variable_name);
                named_tuple_entries.insert(variable_name.clone());

                if variable_symbol.is_some_and(|variable_symbol| variable_symbol.is_class_var()) {
                    // If an ancestor class declared an instance variable but this dataclass
                    // declares a ClassVar, delete the older one from the full data class entries.
                    let index = full_data_class_entries
                        .iter()
                        .position(|p| p.name == variable_name);
                    if let Some(index) = index {
                        full_data_class_entries.remove(index);
                    }
                    let data_class_entry = P::new_eval(DataClassEntry {
                        name: variable_name,
                        class_type,
                        mro_class: None,
                        is_class_var: true,
                        is_keyword_only: false,
                        alias: alias_name,
                        has_default: Cell::new(Some(has_default)),
                        is_default_factory: Some(is_default_factory),
                        name_node: Some(variable_name_node),
                        type_annotation_node,
                        default_expr: Cell::new(default_expr),
                        include_in_init,
                        type_: Cell::new(UnknownType::create(false).0),
                        converter,
                    });
                    local_data_class_entries.push(data_class_entry);
                } else {
                    // Create a new data class entry, but defer evaluation of the type until
                    // we've compiled the full list of data class entries for this class. This
                    // allows us to handle circular references in types.
                    let data_class_entry = P::new_eval(DataClassEntry {
                        name: variable_name.clone(),
                        class_type,
                        mro_class: None,
                        is_class_var: false,
                        is_keyword_only,
                        alias: alias_name,
                        has_default: Cell::new(Some(has_default)),
                        is_default_factory: Some(is_default_factory),
                        name_node: Some(variable_name_node),
                        type_annotation_node,
                        default_expr: Cell::new(default_expr),
                        include_in_init,
                        type_: Cell::new(UnknownType::create(false).0),
                        converter,
                    });
                    local_entry_type_evaluator.push(LocalEntryTypeEvaluator {
                        entry: data_class_entry,
                        evaluator: variable_type_evaluator,
                        is_inferred_final,
                        default_expr,
                    });

                    // Add the new entry to the local entry list.
                    let local_index = local_data_class_entries
                        .iter()
                        .position(|e| e.name == variable_name);
                    if let Some(local_index) = local_index {
                        local_data_class_entries[local_index] = data_class_entry;
                    } else {
                        local_data_class_entries.push(data_class_entry);
                    }

                    // Add the new entry to the full entry list.
                    let insert_index: usize;
                    let full_index = full_data_class_entries
                        .iter()
                        .position(|p| p.name == variable_name);
                    if let Some(full_index) = full_index {
                        let old_entry = full_data_class_entries[full_index];

                        // A bare annotation (`x: int`) inherits a parent field's default at
                        // runtime. An explicit `field()` with no default or default_factory
                        // does not, so the synthesized __init__ parameter is required.
                        if !data_class_entry.has_default.get().unwrap_or(false)
                            && old_entry.has_default.get().unwrap_or(false)
                            && old_entry.include_in_init
                            && !is_field_specifier_without_default
                        {
                            data_class_entry.has_default.set(Some(true));
                            data_class_entry
                                .default_expr
                                .set(old_entry.default_expr.get());
                            has_default = true;

                            // Warn the user of this case because it can result in type errors if the
                            // default value is incompatible with the new type.
                            evaluator.add_diagnostic(
                                DiagnosticRule::reportGeneralTypeIssues,
                                &LocMessage::data_class_field_inherited_default()
                                    .format(&[("fieldName", &variable_name)]),
                                variable_name_node.0,
                                None,
                            );
                        }

                        full_data_class_entries[full_index] = data_class_entry;
                        insert_index = full_index;
                    } else {
                        full_data_class_entries.push(data_class_entry);
                        insert_index = full_data_class_entries.len() - 1;
                    }

                    // If we've already seen a entry with a default value defined,
                    // all subsequent entries must also have default values.
                    if !is_keyword_only && include_in_init && !skip_synthesize_init && !has_default
                    {
                        let first_default_value_index =
                            full_data_class_entries.iter().position(|p| {
                                p.has_default.get().unwrap_or(false)
                                    && p.include_in_init
                                    && !p.is_keyword_only
                            });
                        if let Some(first_default_value_index) = first_default_value_index
                            && first_default_value_index < insert_index
                        {
                            evaluator.add_diagnostic(
                                DiagnosticRule::reportGeneralTypeIssues,
                                &LocMessage::data_class_field_with_default(),
                                variable_name_node.0,
                                None,
                            );
                        }
                    }
                }
            }
        } else {
            // The symbol had no declared type, so it is (mostly) ignored by dataclasses.
            // However, if it is assigned a field descriptor, it will result in a
            // runtime exception.
            let declarations = symbol.get_declarations();
            if declarations.is_empty() {
                return;
            }
            let last_decl = declarations[declarations.len() - 1];
            if last_decl.type_ != DeclarationType::Variable {
                return;
            }

            let statement = last_decl.node.get().parent.get();
            let Some(statement) = statement.and_then(AssignmentNode::cast) else {
                return;
            };

            // If the RHS of the assignment is assigning a field instance where the
            // "init" parameter is set to false, do not include it in the init method.
            if !is_named_tuple
                && let Some(right_expr) = CallNode::cast(statement.d().right_expr.get())
            {
                let call_type = evaluator
                    .get_type_of_expression(
                        right_expr.d().left_expr.get(),
                        EvalFlags::CallBaseDefaults,
                        None,
                    )
                    .type_
                    .get();

                let field_descriptor_names = class_type
                    .d()
                    .shared
                    .get()
                    .data_class_behaviors
                    .get()
                    .map(|behaviors| behaviors.field_descriptor_names.borrow().clone())
                    .unwrap_or_default();
                if is_dataclass_field_constructor(call_type, &field_descriptor_names) {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::data_class_field_without_annotation(),
                        statement.d().right_expr.get(),
                        None,
                    );
                }
            }
        }
    });

    if is_named_tuple {
        *class_type.d().shared.get().named_tuple_entries.borrow_mut() = Some(named_tuple_entries);
    } else {
        *class_type.d().shared.get().data_class_entries.borrow_mut() =
            Some(local_data_class_entries.clone());
    }

    // Now that the dataClassEntries field has been set with a complete list
    // of local data class entries for this class, perform deferred type
    // evaluations. This could involve circular type dependencies, so it's
    // required that the list be complete (even if types are not yet accurate)
    // before we perform the type evaluations.
    for entry_evaluator in &local_entry_type_evaluator {
        let annotation_options = ExpectedTypeOptions {
            allow_final: Some(!is_named_tuple),
            allow_class_var: Some(!is_named_tuple),
            var_type_annotation: Some(true),
            ..Default::default()
        };
        let entry_type = match entry_evaluator.evaluator {
            EntryTypeEvaluator::Assignment(assignment_statement) => {
                if entry_evaluator.is_inferred_final
                    && let Some(default_expr) = entry_evaluator.default_expr
                {
                    evaluator
                        .get_type_of_expression(default_expr, EvalFlags::None, None)
                        .type_
                        .get()
                } else {
                    evaluator.get_type_of_annotation(
                        TypeAnnotationNode::cast(assignment_statement.d().left_expr.get())
                            .unwrap()
                            .d()
                            .annotation
                            .get(),
                        Some(&annotation_options),
                    )
                }
            }
            EntryTypeEvaluator::Annotation(annotation_statement) => evaluator
                .get_type_of_annotation(
                    annotation_statement.d().annotation.get(),
                    Some(&annotation_options),
                ),
        };
        entry_evaluator.entry.type_.set(entry_type);
    }

    let symbol_table = ClassType::get_symbol_table(class_type);
    let mut keyword_only_params: Vec<FunctionParam> = vec![];

    if !skip_synthesize_init && !has_existing_init_method {
        if all_ancestors_known {
            for entry in &full_data_class_entries {
                if entry.include_in_init {
                    let mut default_type: Option<P<Type>> = None;

                    // If the type refers to Self of the parent class, we need to
                    // transform it to refer to the Self of this subclass.
                    let mut effective_type = entry.type_.get();
                    if entry.class_type != class_type
                        && requires_specialization(effective_type, None, 0)
                    {
                        let solution = ConstraintSolution::new(None);
                        add_solution_for_self_type(&solution, entry.class_type, class_type.0);
                        effective_type = apply_solved_type_vars(
                            effective_type,
                            &solution,
                            &ApplyTypeVarOptions::default(),
                        );
                    }

                    // Is the field type a descriptor object? If so, we need to extract the corresponding
                    // type of the __init__ method parameter from the __set__ method.
                    effective_type = transform_descriptor_type(evaluator, effective_type);

                    if let Some(converter) = entry.converter {
                        let field_type = effective_type;
                        effective_type = get_converter_input_type(
                            evaluator,
                            converter,
                            effective_type,
                            &entry.name,
                            node_info,
                        );
                        symbol_table.set(
                            &entry.name,
                            get_descriptor_for_converter_field(
                                evaluator,
                                class_type,
                                node.0,
                                entry.name_node,
                                converter.0,
                                &entry.name,
                                field_type,
                                effective_type,
                                node_info,
                            ),
                        );

                        if entry.has_default.get().unwrap_or(false) {
                            default_type = Some(entry.type_.get());
                        }
                    } else if entry.has_default.get().unwrap_or(false) {
                        if entry.is_default_factory.unwrap_or(false)
                            || entry.default_expr.get().is_none()
                        {
                            default_type = Some(entry.type_.get());
                        } else {
                            let default_expr = entry.default_expr.get().unwrap();
                            let file_info = node_info.get_file_info(node.0);
                            let flags = if file_info.is_stub_file {
                                EvalFlags::ConvertEllipsisToAny
                            } else {
                                EvalFlags::None
                            };
                            let live_type_vars =
                                get_type_var_scopes_for_node(default_expr, node_info.reader());
                            let bound_effective_type =
                                make_type_vars_bound(effective_type, Some(&live_type_vars));

                            // Use speculative mode here so we don't cache the results.
                            // We'll want to re-evaluate this expression later, potentially
                            // with different evaluation flags.
                            let mut evaluated_default_type = evaluator.use_speculative_mode(
                                Some(default_expr),
                                &mut || {
                                    evaluator
                                        .get_type_of_expression(
                                            default_expr,
                                            flags,
                                            make_inference_context(
                                                Some(bound_effective_type),
                                                None,
                                                None,
                                            ),
                                        )
                                        .type_
                                        .get()
                                },
                                None,
                            );

                            evaluated_default_type =
                                make_type_vars_free(evaluated_default_type, &live_type_vars);

                            if let Some(mro_class) = entry.mro_class
                                && requires_specialization(evaluated_default_type, None, 0)
                            {
                                let solution = build_solution_from_specialized_class(mro_class);
                                evaluated_default_type = apply_solved_type_vars(
                                    evaluated_default_type,
                                    &solution,
                                    &ApplyTypeVarOptions::default(),
                                );
                            }

                            default_type = Some(evaluated_default_type);
                        }
                    }

                    let effective_name = match &entry.alias {
                        Some(alias) if !alias.is_empty() => alias.clone(),
                        _ => entry.name.clone(),
                    };

                    if entry.alias.as_ref().is_none_or(|alias| alias.is_empty())
                        && let Some(name_node) = entry.name_node
                        && is_private_name(name_node.d().value())
                    {
                        evaluator.add_diagnostic(
                            DiagnosticRule::reportGeneralTypeIssues,
                            &LocMessage::data_class_field_with_private_name(),
                            name_node.0,
                            None,
                        );
                    }

                    let param = FunctionParam::create(
                        ParamCategory::Simple,
                        effective_type,
                        FunctionParamFlags::TypeDeclared,
                        Some(&effective_name),
                        default_type,
                        entry.default_expr.get(),
                    );

                    if entry.is_keyword_only {
                        keyword_only_params.push(param.clone());
                    } else {
                        FunctionType::add_param(constructor_type, &param);
                    }

                    if let Some(replace_type) = replace_type {
                        let param_with_default = FunctionParam::create(
                            param.category,
                            param._type,
                            param.flags,
                            param.name.as_deref(),
                            Some(AnyType::create(/* isEllipsis */ true).0),
                            None,
                        );

                        FunctionType::add_param(replace_type, &param_with_default);
                    }
                }
            }

            if !keyword_only_params.is_empty() {
                FunctionType::add_keyword_only_param_separator(constructor_type);
                for param in &keyword_only_params {
                    FunctionType::add_param(constructor_type, param);
                }
            }
        }

        symbol_table.set(
            "__init__",
            Symbol::create_with_type(SymbolFlags::ClassMember, init_type.0, None),
        );
        symbol_table.set(
            "__new__",
            Symbol::create_with_type(SymbolFlags::ClassMember, new_type.0, None),
        );

        if let Some(replace_type) = replace_type {
            symbol_table.set(
                "__replace__",
                Symbol::create_with_type(SymbolFlags::ClassMember, replace_type.0, None),
            );
        }
    }

    // Synthesize the __match_args__ class variable if it doesn't exist
    // and match_args behavior is not explicitly disabled.
    let str_type = evaluator.get_built_in_type(node.0, jsrt::atom!("str"));
    let tuple_class_type = evaluator.get_built_in_type(node.0, jsrt::atom!("tuple"));
    if is_instantiable_class(tuple_class_type)
        && is_instantiable_class(str_type)
        && !symbol_table.has("__match_args__")
        && class_type
            .d()
            .shared
            .get()
            .data_class_behaviors
            .get()
            .and_then(|behaviors| behaviors.match_args.get())
            .unwrap_or(true)
    {
        let mut match_args_names: Vec<String> = vec![];
        for entry in &full_data_class_entries {
            if entry.include_in_init && !entry.is_keyword_only {
                // Use the field name, not its alias (if it has one).
                match_args_names.push(entry.name.clone());
            }
        }
        let literal_types: Vec<TupleTypeArg> = match_args_names
            .iter()
            .map(|name| TupleTypeArg {
                type_: ClassType::clone_as_instance(
                    ClassType::clone_with_literal(
                        ClassType(str_type),
                        Some(LiteralValue::String(name.into())),
                    ),
                    true,
                )
                .0,
                is_unbounded: false,
                is_optional: None,
            })
            .collect();
        let match_args_type = ClassType::clone_as_instance(
            specialize_tuple_class(ClassType(tuple_class_type), &literal_types, true, false),
            true,
        );
        symbol_table.set(
            "__match_args__",
            Symbol::create_with_type(SymbolFlags::ClassMember, match_args_type.0, None),
        );
    }

    // analyzer/dataClasses.ts:759
    let synthesize_comparison_method = |operator: &str, param_type: P<Type>| {
        let operator_method =
            FunctionType::create_synthesized_instance(operator, FunctionTypeFlags::None);
        FunctionType::add_param(operator_method, &self_param);
        FunctionType::add_param(
            operator_method,
            &FunctionParam::create(
                ParamCategory::Simple,
                param_type,
                FunctionParamFlags::TypeDeclared,
                Some("other"),
                None,
                None,
            ),
        );
        operator_method
            .d()
            .shared
            .get()
            .declared_return_type
            .set(Some(evaluator.get_built_in_object(node.0, jsrt::atom!("bool"), None)));
        // If a method of this name already exists, don't override it.
        if symbol_table.get(operator).is_none() {
            symbol_table.set(
                operator,
                Symbol::create_with_type(SymbolFlags::ClassMember, operator_method.0, None),
            );
        }
    };

    // Synthesize comparison operators.
    if !ClassType::is_data_class_skip_generate_eq(class_type) {
        synthesize_comparison_method(
            "__eq__",
            evaluator.get_built_in_object(node.0, jsrt::atom!("object"), None),
        );
    }

    if ClassType::is_data_class_generate_order(class_type) {
        for operator in ["__lt__", "__le__", "__gt__", "__ge__"] {
            synthesize_comparison_method(operator, self_type.0);
        }
    }

    let mut synthesize_hash_function = ClassType::is_data_class_frozen(class_type);
    let synthesize_hash_none = !is_named_tuple
        && !ClassType::is_data_class_skip_generate_eq(class_type)
        && !ClassType::is_data_class_frozen(class_type);

    if skip_synthesize_hash {
        synthesize_hash_function = false;
    }

    // If the user has indicated that a hash function should be generated even if it's unsafe
    // to do so or there is already a hash function present, override the default logic.
    if ClassType::is_data_class_generate_hash(class_type) {
        synthesize_hash_function = true;
    }

    if synthesize_hash_function {
        let hash_method =
            FunctionType::create_synthesized_instance("__hash__", FunctionTypeFlags::None);
        FunctionType::add_param(hash_method, &self_param);
        hash_method
            .d()
            .shared
            .get()
            .declared_return_type
            .set(Some(evaluator.get_built_in_object(node.0, jsrt::atom!("int"), None)));
        symbol_table.set(
            "__hash__",
            Symbol::create_with_type(
                SymbolFlags::ClassMember | SymbolFlags::IgnoredForOverrideChecks,
                hash_method.0,
                None,
            ),
        );
    } else if synthesize_hash_none && !skip_synthesize_hash {
        symbol_table.set(
            "__hash__",
            Symbol::create_with_type(
                SymbolFlags::ClassMember | SymbolFlags::IgnoredForOverrideChecks,
                evaluator.get_none_type(),
                None,
            ),
        );
    }

    let mut dict_type = evaluator.get_built_in_type(node.0, jsrt::atom!("dict"));
    if is_instantiable_class(dict_type) {
        let type_args = [
            evaluator.get_built_in_object(node.0, jsrt::atom!("str"), None),
            AnyType::create(false).0,
        ];
        dict_type = ClassType::clone_as_instance(
            ClassType::specialize(
                ClassType(dict_type),
                Some(&type_args),
                None,
                false,
                None,
                None,
            ),
            true,
        )
        .0;
    }

    if !is_named_tuple {
        symbol_table.set(
            "__dataclass_fields__",
            Symbol::create_with_type(
                SymbolFlags::ClassMember | SymbolFlags::ClassVar,
                dict_type,
                None,
            ),
        );
    }

    if ClassType::is_data_class_generate_slots(class_type)
        && class_type
            .d()
            .shared
            .get()
            .local_slots_names
            .borrow()
            .is_none()
    {
        *class_type
            .d()
            .shared
            .get()
            .synthesize_data_class_slots_deferred
            .borrow_mut() = None;

        let inherited_slots_names = get_inherited_data_class_slots_names(class_type);

        let local_slots_names: Vec<String> = local_data_class_entries
            .iter()
            .filter(|entry| {
                !entry.is_class_var
                    && !symbol_table
                        .get(&entry.name)
                        .is_some_and(|symbol| symbol.is_init_var())
                    && !inherited_slots_names.contains(&entry.name)
            })
            .map(|entry| entry.name.clone())
            .collect();
        let has_non_empty_slots = !local_slots_names.is_empty();
        *class_type.d().shared.get().local_slots_names.borrow_mut() = Some(local_slots_names);
        class_type
            .d()
            .shared
            .get()
            .has_non_empty_slots
            .set(Some(has_non_empty_slots));
    }

    // Should we synthesize a __slots__ symbol?
    if ClassType::is_data_class_generate_slots(class_type) {
        let mut iterable_type = evaluator
            .get_typing_type(node.0, "Iterable")
            .unwrap_or_else(|| UnknownType::create(false).0);

        if is_instantiable_class(iterable_type) {
            let type_args = [evaluator.get_built_in_object(node.0, jsrt::atom!("str"), None)];
            iterable_type = ClassType::clone_as_instance(
                ClassType::specialize(
                    ClassType(iterable_type),
                    Some(&type_args),
                    None,
                    false,
                    None,
                    None,
                ),
                true,
            )
            .0;
        }

        symbol_table.set(
            "__slots__",
            Symbol::create_with_type(
                SymbolFlags::ClassMember | SymbolFlags::ClassVar,
                iterable_type,
                None,
            ),
        );
    }

    // If this dataclass derived from a NamedTuple, update the NamedTuple with
    // the specialized entry types.
    let entry_types: Vec<P<Type>> = full_data_class_entries
        .iter()
        .map(|entry| entry.type_.get())
        .collect();
    if update_named_tuple_base_class(class_type, &entry_types, /* isTypeArgExplicit */ true) {
        // The class's base classes were replaced after the class was built.
        crate::analyzer::type_evaluator::note_type_mutation();
        // Recompute the MRO based on the updated NamedTuple base class.
        compute_mro_linearization(class_type);
    }
}

// analyzer/dataClasses.ts:966
// If a field specifier is used to define a field, it may define a default
// argument value (either True or False) for a supported keyword parameter.
// This function extracts that default value if present and returns it. If
// it's not present, it returns undefined.
pub(crate) fn get_default_arg_value_for_field_specifier(
    evaluator: &TypeEvaluator,
    call_node: CallNode,
    call_type_result: P<TypeResult>,
    param_name: &str,
) -> Option<bool> {
    let call_type = call_type_result.type_.get();
    let mut call_target: Option<FunctionType> = None;

    if is_function(call_type) {
        call_target = Some(FunctionType(call_type));
    } else if is_overloaded(call_type) {
        let type_result = P::new_eval(TypeResult {
            is_incomplete: Cell::new(call_type_result.is_incomplete.get()),
            ..TypeResult::new(call_type)
        });
        let arg_nodes: Vec<ArgumentNode> = call_node.d().args.borrow().clone();
        let args: Vec<Arg> = arg_nodes
            .into_iter()
            .map(|arg| Arg::ArgWithExpression(evaluator.convert_node_to_arg(arg)))
            .collect();
        call_target = evaluator.get_best_overload_for_args(call_node.0, type_result, &args);
    } else if is_instantiable_class(call_type) {
        let init_method_result = get_bound_init_method(
            evaluator,
            call_node.0,
            ClassType(call_type),
            None,
            MemberAccessFlags::SkipObjectBaseClass,
        );
        if let Some(init_method_result) = init_method_result {
            let init_method_type = init_method_result.type_.get();
            if is_function(init_method_type) {
                call_target = Some(FunctionType(init_method_type));
            } else if is_overloaded(init_method_type) {
                let type_result = P::new_eval(TypeResult::new(init_method_type));
                let arg_nodes: Vec<ArgumentNode> = call_node.d().args.borrow().clone();
                let args: Vec<Arg> = arg_nodes
                    .into_iter()
                    .map(|arg| Arg::ArgWithExpression(evaluator.convert_node_to_arg(arg)))
                    .collect();
                call_target = evaluator.get_best_overload_for_args(call_node.0, type_result, &args);
            }
        }
    }

    if let Some(call_target) = call_target {
        let init_param_index = call_target
            .d()
            .shared
            .get()
            .parameters
            .get()
            .borrow()
            .iter()
            .position(|p| p.name.as_deref() == Some(param_name));
        if let Some(init_param_index) = init_param_index {
            let init_param =
                call_target.d().shared.get().parameters.get().borrow()[init_param_index].clone();

            // Is the parameter type a literal bool?
            let init_param_type =
                FunctionType::get_param_type(call_target, init_param_index as i32);
            if FunctionParam::is_type_declared(&init_param) && is_class(init_param_type) {
                let literal_value = ClassType(init_param_type)
                    .d()
                    .priv_
                    .borrow()
                    .literal_value
                    .clone();
                if let Some(LiteralValue::Boolean(value)) = literal_value {
                    return Some(value);
                }
            }

            // Is the default argument value a literal bool?
            let init_param_default_type =
                FunctionType::get_param_default_type(call_target, init_param_index as i32);
            if let Some(init_param_default_type) = init_param_default_type
                && is_class(init_param_default_type)
            {
                let literal_value = ClassType(init_param_default_type)
                    .d()
                    .priv_
                    .borrow()
                    .literal_value
                    .clone();
                if let Some(LiteralValue::Boolean(value)) = literal_value {
                    return Some(value);
                }
            }
        }
    }

    None
}

// analyzer/dataClasses.ts:1030
// Validates converter and, if valid, returns its input type. If invalid,
// fieldType is returned.
pub(crate) fn get_converter_input_type(
    evaluator: &TypeEvaluator,
    converter_node: ArgumentNode,
    field_type: P<Type>,
    field_name: &str,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<Type> {
    // Use speculative mode here so we don't cache the results.
    // We'll want to re-evaluate this expression later, potentially
    // with different evaluation flags.
    let value_expr = converter_node.d().value_expr.get();
    let value_type = evaluator.use_speculative_mode(
        Some(value_expr),
        &mut || {
            evaluator
                .get_type_of_expression(value_expr, EvalFlags::NoSpecialize, None)
                .type_
                .get()
        },
        None,
    );

    let converter_type = get_converter_as_function(evaluator, value_type);

    let Some(converter_type) = converter_type else {
        return field_type;
    };

    // Create synthesized function of the form Callable[[T], fieldType] which
    // will be used to check compatibility of the provided converter.
    let type_var = TypeVarType::create_instance("__converterInput", TypeVarKind::TypeVar);
    let scope_id = get_scope_id_for_node(converter_node.0, node_info.reader());
    type_var.d().priv_.borrow_mut().scope_id = Some(scope_id);
    let target_function = FunctionType::create_synthesized_instance("", FunctionTypeFlags::None);
    let type_var_scope_id = type_var.d().priv_.borrow().scope_id;
    *target_function
        .d()
        .shared
        .get()
        .type_var_scope_id
        .borrow_mut() = type_var_scope_id;
    target_function
        .d()
        .shared
        .get()
        .declared_return_type
        .set(Some(field_type));
    FunctionType::add_param(
        target_function,
        &FunctionParam::create(
            ParamCategory::Simple,
            type_var.0,
            FunctionParamFlags::TypeDeclared | FunctionParamFlags::NameSynthesized,
            Some("__input"),
            None,
            None,
        ),
    );
    FunctionType::add_position_only_param_separator(target_function);

    if is_function_or_overloaded(converter_type) {
        let mut accepted_types: Vec<P<Type>> = vec![];
        let diag_addendum = DiagnosticAddendum::new();

        do_for_each_signature(converter_type, &mut |signature, _index| {
            let mut signature: P<Type> = signature.0;
            let return_constraints = ConstraintTracker::new();

            if evaluator.assign_type(
                FunctionType::get_effective_return_type(FunctionType(signature), true)
                    .unwrap_or_else(|| UnknownType::create(false).0),
                field_type,
                /* diag */ None,
                Some(return_constraints),
                AssignTypeFlags::Default,
                0,
            ) {
                signature = evaluator.solve_and_apply_constraints(
                    signature,
                    return_constraints,
                    None,
                    None,
                );
            }

            let input_constraints = ConstraintTracker::new();

            if evaluator.assign_type(
                target_function.0,
                signature,
                Some(diag_addendum),
                Some(input_constraints),
                AssignTypeFlags::Default,
                0,
            ) {
                let overload_solution = evaluator.solve_and_apply_constraints(
                    type_var.0,
                    input_constraints,
                    Some(&ApplyTypeVarOptions {
                        replace_unsolved: Some(ApplyTypeVarOptionsReplaceUnsolved {
                            scope_ids: Rc::from(get_type_var_scope_ids(type_var.0)),
                            tuple_class_type: evaluator.get_tuple_class_type(),
                            unsolved_exempt_type_vars: None,
                            use_unknown: None,
                            eliminate_unsolved_in_unions: None,
                        }),
                        ..Default::default()
                    }),
                    None,
                );
                accepted_types.push(overload_solution);
            }
        });

        if !accepted_types.is_empty() {
            return combine_types(&accepted_types, None);
        }

        if is_function(converter_type) {
            let message = LocMessage::data_class_converter_function().format(&[
                ("argType", &evaluator.print_type(converter_type, None)),
                ("fieldType", &evaluator.print_type(field_type, None)),
                ("fieldName", field_name),
            ]) + &diag_addendum.get_string(
                DEFAULT_MAX_DIAGNOSTIC_DEPTH,
                DEFAULT_MAX_DIAGNOSTIC_LINE_COUNT,
            );
            let range = diag_addendum
                .get_effective_text_range()
                .unwrap_or_else(|| converter_node.text_range());
            evaluator.add_diagnostic(
                DiagnosticRule::reportGeneralTypeIssues,
                &message,
                converter_node.0,
                Some(&range),
            );
        } else {
            let overloads = OverloadedType::get_overloads(OverloadedType(converter_type));
            let func_name =
                if !overloads.is_empty() && !overloads[0].d().shared.get().name.is_empty() {
                    overloads[0].d().shared.get().name.to_string()
                } else {
                    "<anonymous function>".to_string()
                };
            let message = LocMessage::data_class_converter_overloads().format(&[
                ("funcName", &func_name),
                ("fieldType", &evaluator.print_type(field_type, None)),
                ("fieldName", field_name),
            ]) + &diag_addendum.get_string(
                DEFAULT_MAX_DIAGNOSTIC_DEPTH,
                DEFAULT_MAX_DIAGNOSTIC_LINE_COUNT,
            );
            evaluator.add_diagnostic(
                DiagnosticRule::reportGeneralTypeIssues,
                &message,
                converter_node.0,
                None,
            );
        }
    }

    field_type
}

// analyzer/dataClasses.ts:1134
pub(crate) fn get_converter_as_function(
    evaluator: &TypeEvaluator,
    converter_type: P<Type>,
) -> Option<P<Type>> {
    if is_function_or_overloaded(converter_type) {
        return Some(converter_type);
    }

    if is_class_instance(converter_type) {
        return evaluator.get_bound_magic_method(
            ClassType(converter_type),
            "__call__",
            None,
            None,
            None,
            0,
        );
    }

    if is_instantiable_class(converter_type) {
        let from_constructor =
            create_function_from_constructor(evaluator, ClassType(converter_type), None, 0);
        if let Some(mut from_constructor) = from_constructor {
            // If conversion to a constructor resulted in a union type, we'll
            // choose the first of the two subtypes, which typically corresponds
            // to the __init__ method (rather than the __new__ method).
            if is_union(from_constructor) {
                from_constructor = UnionType(from_constructor).d().priv_.borrow().subtypes[0];
            }

            if is_function_or_overloaded(from_constructor) {
                return Some(from_constructor);
            }
        }
    }

    None
}

// analyzer/dataClasses.ts:1170
// Synthesizes an asymmetric descriptor class to be used in place of the
// annotated type of a field with a converter. The descriptor's __get__ method
// returns the declared type of the field and its __set__ method accepts the
// converter's input type. Returns the symbol for an instance of this descriptor
// type.
#[allow(clippy::too_many_arguments)]
pub(crate) fn get_descriptor_for_converter_field(
    evaluator: &TypeEvaluator,
    dataclass: ClassType,
    dataclass_node: P<ParseNode>,
    field_name_node: Option<NameNode>,
    converter_node: P<ParseNode>,
    field_name: &str,
    get_type: P<Type>,
    set_type: P<Type>,
    node_info: &AnalyzerNodeInfoAccessor,
) -> P<Symbol> {
    let file_info = node_info.get_file_info(dataclass_node);
    let type_metaclass = evaluator.get_built_in_type(dataclass_node, jsrt::atom!("type"));
    let descriptor_name = format!("__converterDescriptor_{field_name}");

    let descriptor_class = ClassType::create_instantiable(
        &descriptor_name,
        &get_class_full_name(converter_node, &file_info.module_name, &descriptor_name),
        &file_info.module_name,
        &file_info.file_uri,
        ClassTypeFlags::None,
        get_type_source_id(converter_node),
        /* declaredMetaclass */ None,
        Some(if is_instantiable_class(type_metaclass) {
            type_metaclass
        } else {
            UnknownType::create(false).0
        }),
        None,
    );

    let scope_id = get_scope_id_for_node(converter_node, node_info.reader());
    *descriptor_class
        .d()
        .shared
        .get()
        .type_var_scope_id
        .borrow_mut() = Some(scope_id);

    // Make the descriptor generic, copying the type parameters from the dataclass.
    let dataclass_type_params: Vec<TypeVarType> =
        dataclass.d().shared.get().type_params.borrow().to_vec();
    let descriptor_type_params: Vec<TypeVarType> = dataclass_type_params
        .iter()
        .map(|type_parm| {
            let type_param = TypeVarType::clone_for_scope_id(
                *type_parm,
                scope_id,
                Some(descriptor_class.d().shared.get().name.to_string()),
                Some(TypeVarScopeType::Class),
            );
            type_param.d().priv_.borrow_mut().computed_variance = Some(Variance::Covariant);
            type_param
        })
        .collect();
    *descriptor_class.d().shared.get().type_params.borrow_mut() = Rc::new(descriptor_type_params);

    let descriptor_type_args: Vec<P<Type>> = descriptor_class
        .d()
        .shared
        .get()
        .type_params
        .borrow()
        .iter()
        .map(|type_param| type_param.0)
        .collect();
    let dataclass_type_params: Vec<TypeVarType> =
        dataclass.d().shared.get().type_params.borrow().to_vec();
    let solution = build_solution(&dataclass_type_params, Some(&descriptor_type_args));
    let get_type = apply_solved_type_vars(get_type, &solution, &ApplyTypeVarOptions::default());
    let set_type = apply_solved_type_vars(set_type, &solution, &ApplyTypeVarOptions::default());

    let object_type = evaluator.get_built_in_type(dataclass_node, jsrt::atom!("object"));
    Rc::make_mut(&mut *descriptor_class
        .d()
        .shared
        .get()
        .base_classes
        .borrow_mut())
        .push(object_type);
    compute_mro_linearization(descriptor_class);

    let fields = ClassType::get_symbol_table(descriptor_class);
    let self_type = synthesize_type_var_for_self_cls(descriptor_class, /* isClsParam */ false);

    let set_function =
        FunctionType::create_synthesized_instance("__set__", FunctionTypeFlags::None);
    FunctionType::add_param(
        set_function,
        &FunctionParam::create(
            ParamCategory::Simple,
            self_type.0,
            FunctionParamFlags::TypeDeclared,
            Some("self"),
            None,
            None,
        ),
    );
    FunctionType::add_param(
        set_function,
        &FunctionParam::create(
            ParamCategory::Simple,
            AnyType::create(false).0,
            FunctionParamFlags::TypeDeclared,
            Some("obj"),
            None,
            None,
        ),
    );
    FunctionType::add_param(
        set_function,
        &FunctionParam::create(
            ParamCategory::Simple,
            set_type,
            FunctionParamFlags::TypeDeclared,
            Some("value"),
            None,
            None,
        ),
    );
    set_function
        .d()
        .shared
        .get()
        .declared_return_type
        .set(Some(evaluator.get_none_type()));
    let set_symbol = Symbol::create_with_type(SymbolFlags::ClassMember, set_function.0, None);
    fields.set("__set__", set_symbol);

    let get_function =
        FunctionType::create_synthesized_instance("__get__", FunctionTypeFlags::None);
    FunctionType::add_param(
        get_function,
        &FunctionParam::create(
            ParamCategory::Simple,
            self_type.0,
            FunctionParamFlags::TypeDeclared,
            Some("self"),
            None,
            None,
        ),
    );
    FunctionType::add_param(
        get_function,
        &FunctionParam::create(
            ParamCategory::Simple,
            AnyType::create(false).0,
            FunctionParamFlags::TypeDeclared,
            Some("obj"),
            None,
            None,
        ),
    );
    FunctionType::add_param(
        get_function,
        &FunctionParam::create(
            ParamCategory::Simple,
            AnyType::create(false).0,
            FunctionParamFlags::TypeDeclared,
            Some("objtype"),
            None,
            None,
        ),
    );
    get_function
        .d()
        .shared
        .get()
        .declared_return_type
        .set(Some(get_type));
    let get_symbol = Symbol::create_with_type(SymbolFlags::ClassMember, get_function.0, None);
    fields.set("__get__", get_symbol);

    let instance_type_args: Vec<P<Type>> = dataclass
        .d()
        .shared
        .get()
        .type_params
        .borrow()
        .iter()
        .map(|type_param| type_param.0)
        .collect();
    let descriptor_instance = ClassType::specialize(
        ClassType::clone_as_instance(descriptor_class, true),
        Some(&instance_type_args),
        None,
        false,
        None,
        None,
    );

    Symbol::create_with_type(
        SymbolFlags::ClassMember,
        descriptor_instance.0,
        field_name_node,
    )
}

// analyzer/dataClasses.ts:1265
// If the specified type is a descriptor — in particular, if it implements a
// __set__ method, this method transforms the type into the input parameter
// for the set method.
pub(crate) fn transform_descriptor_type(evaluator: &TypeEvaluator, type_: P<Type>) -> P<Type> {
    if !is_class_instance(type_) || is_metaclass_instance(type_) {
        return type_;
    }

    let set_method_type =
        evaluator.get_bound_magic_method(ClassType(type_), "__set__", None, None, None, 0);
    let Some(set_method_type) = set_method_type else {
        return type_;
    };

    if !is_function(set_method_type) {
        return type_;
    }

    // The value parameter for a bound __set__ method is parameter index 1.
    FunctionType::get_param_type(FunctionType(set_method_type), 1)
}

// analyzer/dataClasses.ts:1287
// Builds a sorted list of dataclass entries that are inherited by
// the specified class. These entries must be unique and in reverse-MRO
// order. Returns true if all of the class types in the hierarchy are
// known, false if one or more are unknown.
pub fn add_inherited_data_class_entries(
    class_type: ClassType,
    entries: &mut Vec<P<DataClassEntry>>,
) -> bool {
    let mut all_ancestors_are_known = true;

    for mro_class in ClassType::get_reverse_mro(class_type) {
        if is_instantiable_class(mro_class) {
            let mro_class = ClassType(mro_class);
            let solution = build_solution_from_specialized_class(mro_class);
            let data_class_entries = ClassType::get_data_class_entries(mro_class);

            // Add the entries to the end of the list, replacing same-named
            // entries if found.
            for entry in data_class_entries {
                let existing_index = entries.iter().position(|e| e.name == entry.name);

                // If the type from the parent class is generic, we need to convert
                // to the type parameter namespace of child class.
                let updated_entry = P::new_eval(DataClassEntry {
                    name: entry.name.clone(),
                    class_type: entry.class_type,
                    mro_class: Some(mro_class),
                    is_class_var: entry.is_class_var,
                    is_keyword_only: entry.is_keyword_only,
                    alias: entry.alias.clone(),
                    has_default: Cell::new(entry.has_default.get()),
                    is_default_factory: entry.is_default_factory,
                    name_node: entry.name_node,
                    type_annotation_node: entry.type_annotation_node,
                    default_expr: Cell::new(entry.default_expr.get()),
                    include_in_init: entry.include_in_init,
                    type_: Cell::new(entry.type_.get()),
                    converter: entry.converter,
                });
                updated_entry.type_.set(apply_solved_type_vars(
                    updated_entry.type_.get(),
                    &solution,
                    &ApplyTypeVarOptions::default(),
                ));

                if entry.is_class_var {
                    // If this entry is a class variable, it overrides an existing
                    // instance variable, so delete it.
                    if let Some(existing_index) = existing_index {
                        entries.remove(existing_index);
                    }
                } else if let Some(existing_index) = existing_index {
                    entries[existing_index] = updated_entry;
                } else {
                    entries.push(updated_entry);
                }
            }
        } else {
            all_ancestors_are_known = false;
        }
    }

    all_ancestors_are_known
}

// analyzer/dataClasses.ts:1325
pub(crate) fn is_dataclass_field_constructor(
    type_: P<Type>,
    field_descriptor_names: &[String],
) -> bool {
    let mut call_name: Option<String> = None;

    if is_function(type_) {
        call_name = Some(FunctionType(type_).d().shared.get().full_name.to_string());
    } else if is_overloaded(type_) {
        let overloads = OverloadedType::get_overloads(OverloadedType(type_));
        if !overloads.is_empty() {
            call_name = Some(overloads[0].d().shared.get().full_name.to_string());
        }
    } else if is_instantiable_class(type_) {
        call_name = Some(ClassType(type_).d().shared.get().full_name.to_string());
    }

    let Some(call_name) = call_name.filter(|call_name| !call_name.is_empty()) else {
        return false;
    };

    field_descriptor_names.contains(&call_name)
}

// analyzer/dataClasses.ts:1346
pub fn validate_data_class_transform_decorator(
    evaluator: &TypeEvaluator,
    node: CallNode,
    node_info: &AnalyzerNodeInfoAccessor,
) -> Option<P<DataClassBehaviors>> {
    let behaviors = P::new_eval(DataClassBehaviors {
        skip_generate_init: Cell::new(Some(false)),
        skip_generate_eq: Cell::new(Some(false)),
        generate_order: Cell::new(Some(false)),
        generate_slots: Cell::new(Some(false)),
        generate_hash: Cell::new(Some(false)),
        match_args: Cell::new(None),
        keyword_only: Cell::new(Some(false)),
        frozen: Cell::new(Some(false)),
        frozen_default: Cell::new(Some(false)),
        field_descriptor_names: RefCell::new(vec![]),
    });

    let file_info = node_info.get_file_info(node.0);

    // Parse the arguments to the call.
    let args: Vec<ArgumentNode> = node.d().args.borrow().clone();
    for arg in args {
        let arg_name = arg.d().name.get();
        let Some(arg_name) = arg_name.filter(|_| arg.d().arg_category.get() == ArgCategory::Simple)
        else {
            evaluator.add_diagnostic(
                DiagnosticRule::reportCallIssue,
                &LocMessage::data_class_transform_positional_param(),
                arg.0,
                None,
            );
            continue;
        };

        match arg_name.d().value() {
            "kw_only_default" => {
                let value = evaluate_static_bool_expression(
                    arg.d().value_expr.get(),
                    &file_info.execution_environment,
                    &file_info.defined_constants,
                    None,
                    None,
                );
                let Some(value) = value else {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::data_class_transform_expected_bool_literal(),
                        arg.d().value_expr.get(),
                        None,
                    );
                    continue;
                };

                behaviors.keyword_only.set(Some(value));
            }

            "eq_default" => {
                let value = evaluate_static_bool_expression(
                    arg.d().value_expr.get(),
                    &file_info.execution_environment,
                    &file_info.defined_constants,
                    None,
                    None,
                );
                let Some(value) = value else {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::data_class_transform_expected_bool_literal(),
                        arg.d().value_expr.get(),
                        None,
                    );
                    continue;
                };

                behaviors.skip_generate_eq.set(Some(!value));
            }

            "order_default" => {
                let value = evaluate_static_bool_expression(
                    arg.d().value_expr.get(),
                    &file_info.execution_environment,
                    &file_info.defined_constants,
                    None,
                    None,
                );
                let Some(value) = value else {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::data_class_transform_expected_bool_literal(),
                        arg.d().value_expr.get(),
                        None,
                    );
                    continue;
                };

                behaviors.generate_order.set(Some(value));
            }

            "frozen_default" => {
                let value = evaluate_static_bool_expression(
                    arg.d().value_expr.get(),
                    &file_info.execution_environment,
                    &file_info.defined_constants,
                    None,
                    None,
                );
                let Some(value) = value else {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::data_class_transform_expected_bool_literal(),
                        arg.d().value_expr.get(),
                        None,
                    );
                    continue;
                };

                behaviors.frozen.set(Some(value));

                // Store the frozen default separately because any class that
                // doesn't explicitly specify a frozen value will inherit this
                // value rather than the value from its parent.
                behaviors.frozen_default.set(Some(value));
            }

            // Earlier versions of the dataclass_transform spec used the name "field_descriptors"
            // rather than "field_specifiers". The older name is now deprecated but still supported
            // for the time being because some libraries shipped with the older __dataclass_transform__
            // form that supported this older parameter name.
            "field_descriptors" | "field_specifiers" => {
                let value_type = evaluator
                    .get_type_of_expression(arg.d().value_expr.get(), EvalFlags::None, None)
                    .type_
                    .get();
                let tuple_type_args = if !is_class_instance(value_type)
                    || !ClassType::is_built_in(ClassType(value_type), Some(&[jsrt::atom!("tuple")]))
                {
                    None
                } else {
                    ClassType(value_type)
                        .d()
                        .priv_
                        .borrow()
                        .tuple_type_args
                        .map(|tuple_type_args| tuple_type_args.borrow().clone())
                };
                let Some(tuple_type_args) = tuple_type_args.filter(|tuple_type_args| {
                    !tuple_type_args.iter().any(|entry| {
                        !is_instantiable_class(entry.type_)
                            && !is_function_or_overloaded(entry.type_)
                    })
                }) else {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::data_class_transform_field_specifier()
                            .format(&[("type", &evaluator.print_type(value_type, None))]),
                        arg.d().value_expr.get(),
                        None,
                    );
                    continue;
                };

                for tuple_arg in &tuple_type_args {
                    if is_instantiable_class(tuple_arg.type_) {
                        behaviors.field_descriptor_names.borrow_mut().push(
                            ClassType(tuple_arg.type_)
                                .d()
                                .shared
                                .get()
                                .full_name
                                .to_string(),
                        );
                    } else if is_function(tuple_arg.type_) {
                        behaviors.field_descriptor_names.borrow_mut().push(
                            FunctionType(tuple_arg.type_)
                                .d()
                                .shared
                                .get()
                                .full_name
                                .to_string(),
                        );
                    } else if is_overloaded(tuple_arg.type_) {
                        let overloads =
                            OverloadedType::get_overloads(OverloadedType(tuple_arg.type_));
                        if !overloads.is_empty() {
                            behaviors
                                .field_descriptor_names
                                .borrow_mut()
                                .push(overloads[0].d().shared.get().full_name.to_string());
                        }
                    }
                }
            }

            _ => {
                evaluator.add_diagnostic(
                    DiagnosticRule::reportGeneralTypeIssues,
                    &LocMessage::data_class_transform_unknown_argument()
                        .format(&[("name", arg_name.d().value())]),
                    arg.d().value_expr.get(),
                    None,
                );
            }
        }
    }

    Some(behaviors)
}

// analyzer/dataClasses.ts:1509
pub fn get_dataclass_decorator_behaviors(type_: P<Type>) -> Option<P<DataClassBehaviors>> {
    let mut function_type: Option<FunctionType> = None;
    if is_function(type_) {
        function_type = Some(FunctionType(type_));
    } else if is_overloaded(type_) {
        // Find the first overload or implementation that contains a
        // dataclass_transform decorator. If more than one have such a decorator,
        // only the first one will be honored, as per PEP 681.
        let overloads = OverloadedType::get_overloads(OverloadedType(type_));
        let impl_ = OverloadedType::get_implementation(OverloadedType(type_));

        function_type = overloads.iter().copied().find(|overload| {
            overload
                .d()
                .shared
                .get()
                .cold().decorator_data_class_behaviors
                .is_some()
        });

        if function_type.is_none()
            && let Some(impl_) = impl_
            && is_function(impl_)
            && FunctionType(impl_)
                .d()
                .shared
                .get()
                .cold().decorator_data_class_behaviors
                .is_some()
        {
            function_type = Some(FunctionType(impl_));
        }

        if function_type.is_none() && !overloads.is_empty() {
            function_type = Some(overloads[0]);
        }
    }

    let function_type = function_type?;

    if let Some(behaviors) = function_type
        .d()
        .shared
        .get()
        .cold().decorator_data_class_behaviors
    {
        return Some(behaviors);
    }

    // Is this the built-in dataclass? If so, return the default behaviors.
    if function_type.d().shared.get().full_name == "dataclasses.dataclass" {
        return Some(P::new_eval(DataClassBehaviors {
            skip_generate_init: Cell::new(None),
            skip_generate_eq: Cell::new(None),
            generate_order: Cell::new(None),
            generate_slots: Cell::new(None),
            generate_hash: Cell::new(None),
            match_args: Cell::new(None),
            keyword_only: Cell::new(None),
            frozen: Cell::new(None),
            frozen_default: Cell::new(None),
            field_descriptor_names: RefCell::new(vec![
                "dataclasses.field".to_string(),
                "dataclasses.Field".to_string(),
            ]),
        }));
    }

    None
}

// analyzer/dataClasses.ts:1549
pub(crate) fn apply_data_class_behavior_override(
    evaluator: &TypeEvaluator,
    error_node: P<ParseNode>,
    class_type: ClassType,
    arg_name: &str,
    arg_value_expr: ExpressionNode,
    behaviors: P<DataClassBehaviors>,
    node_info: &AnalyzerNodeInfoAccessor,
) {
    let file_info = node_info.get_file_info(error_node);
    let value = evaluate_static_bool_expression(
        arg_value_expr,
        &file_info.execution_environment,
        &file_info.defined_constants,
        None,
        None,
    );

    apply_data_class_behavior_override_value(
        evaluator, error_node, class_type, arg_name, value, behaviors,
    );
}

// analyzer/dataClasses.ts:1564
pub(crate) fn apply_data_class_behavior_override_value(
    evaluator: &TypeEvaluator,
    error_node: P<ParseNode>,
    class_type: ClassType,
    arg_name: &str,
    arg_value: Option<bool>,
    behaviors: P<DataClassBehaviors>,
) {
    match arg_name {
        "order" => {
            if let Some(arg_value) = arg_value {
                behaviors.generate_order.set(Some(arg_value));
            }
        }

        "kw_only" => {
            if let Some(arg_value) = arg_value {
                behaviors.keyword_only.set(Some(arg_value));
            }
        }

        "match_args" => {
            if let Some(arg_value) = arg_value {
                behaviors.match_args.set(Some(arg_value));
            }
        }

        "frozen" => {
            let mut has_unfrozen_base_class = false;
            let mut has_frozen_base_class = false;

            if let Some(arg_value) = arg_value {
                behaviors.frozen.set(Some(arg_value));
            }

            let base_classes: Vec<P<Type>> =
                class_type.d().shared.get().base_classes.borrow().to_vec();
            for base_class in base_classes {
                if is_instantiable_class(base_class)
                    && ClassType::is_data_class(ClassType(base_class))
                {
                    let base_class = ClassType(base_class);
                    if ClassType::is_data_class_frozen(base_class) {
                        has_frozen_base_class = true;
                    } else if base_class
                        .d()
                        .shared
                        .get()
                        .class_data_class_transform
                        .get()
                        .is_none()
                        && !base_class
                            .d()
                            .shared
                            .get()
                            .declared_metaclass
                            .get()
                            .is_some_and(|declared_metaclass| {
                                is_instantiable_class(declared_metaclass)
                                    && ClassType(declared_metaclass)
                                        .d()
                                        .shared
                                        .get()
                                        .class_data_class_transform
                                        .get()
                                        .is_some()
                            })
                    {
                        // If this base class is unfrozen and isn't the class that directly
                        // references the metaclass that provides dataclass-like behaviors,
                        // we'll assume we're deriving from an unfrozen dataclass.
                        has_unfrozen_base_class = true;
                    }
                }
            }

            if arg_value == Some(true) {
                // A frozen dataclass cannot derive from a non-frozen dataclass.
                if has_unfrozen_base_class {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::data_class_base_class_not_frozen(),
                        error_node,
                        None,
                    );
                }
            } else {
                // A non-frozen dataclass cannot derive from a frozen dataclass.
                if has_frozen_base_class {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::data_class_base_class_frozen(),
                        error_node,
                        None,
                    );
                }
            }
        }

        "init" => {
            if let Some(arg_value) = arg_value {
                behaviors.skip_generate_init.set(Some(!arg_value));
            }
        }

        "eq" => {
            if let Some(arg_value) = arg_value {
                behaviors.skip_generate_eq.set(Some(!arg_value));
            }
        }

        "slots" => {
            if arg_value == Some(true) {
                behaviors.generate_slots.set(Some(true));

                if class_type
                    .d()
                    .shared
                    .get()
                    .local_slots_names
                    .borrow()
                    .is_some()
                {
                    evaluator.add_diagnostic(
                        DiagnosticRule::reportGeneralTypeIssues,
                        &LocMessage::data_class_slots_overwrite(),
                        error_node,
                        None,
                    );
                }
            } else if arg_value == Some(false) {
                behaviors.generate_slots.set(Some(false));
            }
        }

        "hash" | "unsafe_hash" if arg_value == Some(true) => {
            behaviors.generate_hash.set(Some(true));
        }

        _ => {}
    }
}

// analyzer/dataClasses.ts:1678
pub fn apply_data_class_class_behavior_overrides(
    evaluator: &TypeEvaluator,
    error_node: P<ParseNode>,
    class_type: ClassType,
    args: &[Arg],
    default_behaviors: P<DataClassBehaviors>,
    node_info: &AnalyzerNodeInfoAccessor,
) {
    let mut saw_frozen_arg = false;

    // `{ ...defaultBehaviors }`. The copy shares `fieldDescriptorNames` with the
    // original in TypeScript; nothing writes that array after it is built.
    let behaviors = P::new_eval(DataClassBehaviors {
        skip_generate_init: Cell::new(default_behaviors.skip_generate_init.get()),
        skip_generate_eq: Cell::new(default_behaviors.skip_generate_eq.get()),
        generate_order: Cell::new(default_behaviors.generate_order.get()),
        generate_slots: Cell::new(default_behaviors.generate_slots.get()),
        generate_hash: Cell::new(default_behaviors.generate_hash.get()),
        match_args: Cell::new(default_behaviors.match_args.get()),
        keyword_only: Cell::new(default_behaviors.keyword_only.get()),
        frozen: Cell::new(default_behaviors.frozen.get()),
        frozen_default: Cell::new(default_behaviors.frozen_default.get()),
        field_descriptor_names: RefCell::new(
            default_behaviors.field_descriptor_names.borrow().clone(),
        ),
    });

    // The "frozen" behavior is not inherited from the parent class.
    // Instead, it comes from the default.
    behaviors.frozen.set(behaviors.frozen_default.get());

    class_type
        .d()
        .shared
        .get()
        .data_class_behaviors
        .set(Some(behaviors));

    for arg in args {
        if let Some(value_expression) = arg.value_expression()
            && let Some(name) = arg.name()
        {
            apply_data_class_behavior_override(
                evaluator,
                name.0,
                class_type,
                name.d().value(),
                value_expression,
                behaviors,
                node_info,
            );

            if name.d().value() == "frozen" {
                saw_frozen_arg = true;
            }
        }
    }

    // If there was no frozen argument, it is implicitly set to the frozenDefault.
    // This check validates that we're not overriding a frozen class with a
    // non-frozen class or vice versa.
    if !saw_frozen_arg {
        apply_data_class_behavior_override_value(
            evaluator,
            error_node,
            class_type,
            "frozen",
            default_behaviors.frozen_default.get(),
            behaviors,
        );
    }
}

// analyzer/dataClasses.ts:1729
pub fn apply_data_class_decorator(
    evaluator: &TypeEvaluator,
    error_node: P<ParseNode>,
    class_type: ClassType,
    default_behaviors: P<DataClassBehaviors>,
    call_node: Option<CallNode>,
    node_info: &AnalyzerNodeInfoAccessor,
) {
    let arg_nodes: Vec<ArgumentNode> = call_node
        .map(|call_node| call_node.d().args.borrow().clone())
        .unwrap_or_default();
    let args: Vec<Arg> = arg_nodes
        .into_iter()
        .map(|arg| Arg::ArgWithExpression(evaluator.convert_node_to_arg(arg)))
        .collect();
    apply_data_class_class_behavior_overrides(
        evaluator,
        error_node,
        class_type,
        &args,
        default_behaviors,
        node_info,
    );
}
